/* Keypad hit test: '7','4','1' / '8','5','2' / '9','6','3' by column/row. */
uint8_t opeu_transfer_keypad_hit(uint8_t ds[65536], uint16_t x, uint16_t y) {
  uint16_t a;
  uint8_t  b;
  b = 0xff;
  a = W16(PX << 3);
  if (W16(a + 0x48) <= x && W16(a + 0x68) > x) {
    if (W16(PY + 0x23) <= y && W16(PY + 0x3f) > y)
      b = '7';
    if (W16(PY + 0x3f) <= y && W16(PY + 0x5b) > y)
      b = '4';
    if (W16(PY + 0x5b) <= y && W16(PY + 0x77) > y)
      b = '1';
  }
  if (W16(a + 0x68) <= x && W16(a + 0x98) > x) {
    if (W16(PY + 0x23) <= y && W16(PY + 0x3f) > y)
      b = '8';
    if (W16(PY + 0x3f) <= y && W16(PY + 0x5b) > y)
      b = '5';
    if (W16(PY + 0x5b) <= y && W16(PY + 0x77) > y)
      b = '2';
  }
  if (W16(a + 0x98) <= x && W16(a + 0xb8) > x) {
    if (W16(PY + 0x23) <= y && W16(PY + 0x3f) > y)
      b = '9';
    if (W16(PY + 0x3f) <= y && W16(PY + 0x5b) > y)
      b = '6';
    if (W16(PY + 0x5b) <= y && W16(PY + 0x77) > y)
      b = '3';
  }
  return b;
}

/* Mouse mode: right button = Enter (13); a left click on keypad keys 8/5/2
 * selects row 0/1/2 (returning 0xff). Keyboard mode returns the key. */
uint8_t opeu_transfer_input(uint8_t ds[65536], HostWordsEvent event,
                            uint16_t row) {
  uint16_t a, b;
  uint8_t  c;
  if (INPUT_MODE) {
    MOUSE_SHOW();
    INPUT_DELAY(3);
    for (;;) {
      MOUSE_POSITION(a, b);
      if (RIGHT_DOWN()) {
        c = 13;
        break;
      }
      if (LEFT_DOWN()) {
        c = KEYPAD(a, b);
        if (c == '8') {
          SET_ROW(0);
          c = 0xff;
        }
        if (c == '5') {
          SET_ROW(1);
          c = 0xff;
        }
        if (c == '2') {
          SET_ROW(2);
          c = 0xff;
        }
        break;
      }
    }
    MOUSE_HIDE();
    return c;
  }
  return KEY();
}

void opeu_transfer_set(uint8_t ds[65536], uint8_t side, uint8_t row,
                       uint8_t column, uint16_t value) {
  uint16_t at            = TABLE_AT(side, row, column);
  ds[at]                 = (uint8_t)value;
  ds[(uint16_t)(at + 1)] = (uint8_t)(value >> 8);
}

uint16_t opeu_transfer_get(const uint8_t ds[65536], uint8_t side, uint8_t row,
                           uint8_t column) {
  return WORD(TABLE_AT(side, row, column));
}

/* Human player only: title the panel, restore its background and centre the
 * two names (at most ten characters each). */
void opeu_transfer_draw(uint8_t ds[65536], HostWordsEvent event, uint16_t first,
                        uint16_t second) {
  INT16 a;
  if (HUMAN) {
    TITLE();
    MAP_DIALOG();
    RESTORE();
    a = LENGTH(first);
    if (a > 10)
      a = 10;
    POSITION(HALF(a) + PX + 2, PY + 14);
    PRINT1(NAME_FORMAT, first);
    a = LENGTH(second);
    if (a > 10)
      a = 10;
    POSITION(HALF(a) + PX + 20, PY + 14);
    PRINT1(NAME_TEXT, second);
  }
}

/* Right-aligned decimal digits drawn leftwards from x; zero draws one digit. */
void opeu_transfer_digits(uint8_t ds[65536], HostWordsEvent event, uint16_t x,
                          uint16_t y, uint16_t value) {
  for (;; x -= 6) {
    GLYPH(x, y, 0U, BLANK_GLYPH);
    GLYPH(x, y, 7, DIGIT_GLYPH(value % 10));
    if (!(value /= 10))
      break;
  }
}

/* Redraw one row (human player only): both amounts and both fill
 * percentages. column (the column just changed) is not used. The (int)
 * casts of the box/digit y coordinates are needed by the byte proof: they
 * keep the zero-extended row in DI and reload row*28 into SI there. */
void opeu_transfer_draw_row(uint8_t ds[65536], HostWordsEvent event,
                            uint8_t row, uint8_t column) {
  uint16_t a, b, c, d, e, f;
  (void)column;
  if (HUMAN) {
    c = GET(0, row, 0);
    d = GET(1, row, 0);
    e = GET(0, row, 1);
    f = GET(1, row, 1);
    a = PERCENT(c, e);
    b = PERCENT(d, f);
    POSITION(PX + 2, row * 28 + PY + 0x24);
    PRINT1(AMOUNT_FORMAT, c);
    POSITION(PX + 0x19, row * 28 + PY + 0x24);
    PRINT1(AMOUNT_TEXT, d);
    BOX(PX + 2, BOX_Y(row * 28 + PY + 0x37));
    DIGITS((PX + 4) << 3, BOX_Y(row * 28 + PY + 0x37), a);
    BOX(PX + 0x19, BOX_Y(row * 28 + PY + 0x37));
    DIGITS((PX + 0x1b) << 3, BOX_Y(row * 28 + PY + 0x37), b);
    PRINT0(COLOUR);
  }
}

/* Computer player key for row: a, b are the sides' targets (column 2), c, d
 * their amounts. Supplies move toward side 0 ('7'/'4'/'1') while its target
 * exceeds its amount and side 1 holds more than its target, or toward side 1
 * ('9'/'6'/'3') in the opposite case; the step size compares the unsigned
 * difference target - amount with 100 and 10 (so a toward-side-0 move is
 * always '7'). The direction latch AUTO ('<', '>', '-') stops oscillation.
 * Otherwise '2' selects the next row, and Enter (13) ends after row 2. */
uint8_t opeu_transfer_auto_key(uint8_t ds[65536], uint8_t row) {
  uint16_t a, b, c, d;
  c = GET(0, row, 0);
  d = GET(1, row, 0);
  a = GET(0, row, 2);
  b = GET(1, row, 2);
  if (AUTO != '>' && a > c && b < d) {
    AUTO = '<';
    if (W16(b - d) >= 100)
      return '7';
    if (W16(b - d) >= 10)
      return '4';
    return '1';
  }
  if (AUTO != '<' && a < c && b > d) {
    AUTO = '>';
    if (W16(a - c) >= 100)
      return '9';
    if (W16(a - c) >= 10)
      return '6';
    return '3';
  }
  if (row == 2)
    return 13;
  AUTO = '-';
  return '2';
}

