    case 23:
      r = (uint16_t)opeu_ui_highlight(ARG(0), ARG(1), ARG(2), ARG(3), ARG(4));
      break;
    case 24: opeu_unit_report(ds, port_dialogs_host(), ARG(0), ARG(1)); break;
    case 25: r = opeu_unit_selection_eligible(ds, ARG(0)); break;
    case 26:
